using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train the ML model at startup
var modelService = new TicketModelService();
var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "tickets.csv");
modelService.Train(dataPath);

builder.Services.AddSingleton(modelService);
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromModel(modelService.CreatePredictionEngine().Model);

var app = builder.Build();

var metrics = modelService.Metrics;
app.Logger.LogInformation(
    "Model trained — MacroAccuracy: {Macro:F4}, MicroAccuracy: {Micro:F4}, LogLoss: {LogLoss:F4}",
    metrics.MacroAccuracy, metrics.MicroAccuracy, metrics.LogLoss);

app.MapControllers();
app.Run();

