+using Microsoft.ML;
+using Microsoft.ML.Data;
+using TicketClassifier.Models;
+
+namespace TicketClassifier.Services;
+
+public sealed class TicketModelService
+{
+    private readonly MLContext _mlContext = new(seed: 42);
+    private ITransformer _model = null!;
+    private string[] _categoryLabels = [];
+
+    public MulticlassClassificationMetrics Metrics { get; private set; } = null!;
+
+    public void Train(string dataPath)
+    {
+        IDataView data = _mlContext.Data.LoadFromTextFile<TicketData>(
+            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);
+
+        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);
+
+        var pipeline = _mlContext.Transforms.Conversion
+                .MapValueToKey("Label", nameof(TicketData.Category))
+            .Append(_mlContext.Transforms.Text.FeaturizeText(
+                "SubjectFeaturized", nameof(TicketData.Subject)))
+            .Append(_mlContext.Transforms.Text.FeaturizeText(
+                "DescriptionFeaturized", nameof(TicketData.Description)))
+            .Append(_mlContext.Transforms.Concatenate("Features",
+                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
+            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
+            .Append(_mlContext.MulticlassClassification.Trainers
+                .SdcaMaximumEntropy("Label", "Features"))
+            .Append(_mlContext.Transforms.Conversion
+                .MapKeyToValue("PredictedLabel"));
+
+        _model = pipeline.Fit(split.TrainSet);
+
+        // Extract ordered category labels for confidence mapping
+        VBuffer<ReadOnlyMemory<char>> labels = default;
+        split.TrainSet.Schema["Label"].GetKeyValues(ref labels);
+        _categoryLabels = labels.DenseValues().Select(v => v.ToString()).ToArray();
+
+        IDataView predictions = _model.Transform(split.TestSet);
+        Metrics = _mlContext.MulticlassClassification.Evaluate(predictions, "Label");
+    }
+
+    public PredictionEngine<TicketData, TicketPrediction> CreatePredictionEngine()
+        => _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(_model);
+
+    public string[] CategoryLabels => _categoryLabels;
+}
