using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);

// Train the ML model at startup
var modelService = new TicketModelService();
var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "tickets.csv");
modelService.Train(dataPath);

var modelPath = modelService.GetModelPath(dataPath);
modelService.SaveModel(modelPath, modelService.TrainSchema);

builder.Services.AddSingleton(modelService);
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

var metrics = modelService.Metrics;
app.Logger.LogInformation(
    "Model trained — MacroAccuracy: {Macro:F4}, MicroAccuracy: {Micro:F4}, LogLoss: {LogLoss:F4}",
    metrics.MacroAccuracy, metrics.MicroAccuracy, metrics.LogLoss);

app.MapPost("/api/ticket/classify", (
    TicketRequest request,
    PredictionEnginePool<TicketData, TicketPrediction> predictionPool,
    TicketModelService svc) =>
{
    if (string.IsNullOrWhiteSpace(request.Subject) || string.IsNullOrWhiteSpace(request.Description))
        return Results.BadRequest("Subject and Description are required.");

    if (request.Priority is < 1 or > 3)
        return Results.BadRequest("Priority must be between 1 and 3.");

    var input = new TicketData
    {
        Subject = request.Subject,
        Description = request.Description,
        Priority = request.Priority,
    };

    var prediction = predictionPool.Predict(input);
    var labels = svc.CategoryLabels;
    var confidence = new Dictionary<string, float>();
    for (int i = 0; i < labels.Length && i < prediction.Score.Length; i++)
        confidence[labels[i]] = prediction.Score[i];

    return Results.Ok(new TicketPredictionResponse
    {
        PredictedCategory = prediction.Category,
        Confidence = confidence,
    });
});

app.MapGet("/api/ticket/metrics", (TicketModelService svc) =>
{
    var m = svc.Metrics;
    return Results.Ok(new
    {
        m.MacroAccuracy,
        m.MicroAccuracy,
        m.LogLoss,
        m.LogLossReduction,
    });
});

app.Run();

