1. using Microsoft.ML;
2. using Microsoft.ML.Data;
3. using TicketClassifier.Models;
4. 
5. namespace TicketClassifier.Services;
6. 
7. public sealed class TicketModelService
8. {
9.     private readonly MLContext _mlContext = new(seed: 42);
10.     private ITransformer _model = null!;
11.     private string[] _categoryLabels = [];
12. 
13.     public MulticlassClassificationMetrics Metrics { get; private set; } = null!;
14.     public DataViewSchema TrainSchema { get; private set; } = null!;
15. 
16.     public void Train(string dataPath)
17.     {
18.         IDataView data = _mlContext.Data.LoadFromTextFile<TicketData>(
19.             dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);
20. 
21.         var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);
22. 
23.         var pipeline = _mlContext.Transforms.Conversion
24.                 .MapValueToKey("Label", nameof(TicketData.Category))
25.             .Append(_mlContext.Transforms.Text.FeaturizeText(
26.                 "SubjectFeaturized", nameof(TicketData.Subject)))
27.             .Append(_mlContext.Transforms.Text.FeaturizeText(
28.                 "DescriptionFeaturized", nameof(TicketData.Description)))
29.             .Append(_mlContext.Transforms.Concatenate("Features",
30.                 "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
31.             .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
32.             .Append(_mlContext.MulticlassClassification.Trainers
33.                 .SdcaMaximumEntropy("Label", "Features"))
34.             .Append(_mlContext.Transforms.Conversion
35.                 .MapKeyToValue("PredictedLabel"));
36. 
37.         _model = pipeline.Fit(split.TrainSet);
38. 
39.         // Extract ordered category labels for confidence mapping
40.         VBuffer<ReadOnlyMemory<char>> labels = default;
41.         split.TrainSet.Schema["Label"].GetKeyValues(ref labels);
42.         _categoryLabels = labels.DenseValues().Select(v => v.ToString()).ToArray();
43. 
44.         TrainSchema = split.TrainSet.Schema;
45. 
46.         IDataView predictions = _model.Transform(split.TestSet);
47.         Metrics = _mlContext.MulticlassClassification.Evaluate(predictions, "Label");
48.     }
49. 
50.     public void SaveModel(string modelPath, DataViewSchema schema)
51.     {
52.         _mlContext.Model.Save(_model, schema, modelPath);
53.     }
54. 
55.     public string GetModelPath(string dataPath)
56.     {
57.         var dir = Path.GetDirectoryName(dataPath)!;
58.         return Path.Combine(dir, "ticket-model.zip");
59.     }
60. 
61.     public string[] CategoryLabels => _categoryLabels;
62. }
63.

