                 .MapKeyToValue("PredictedLabel"));

         _model = pipeline.Fit(split.TrainSet);

         // Extract ordered category labels for confidence mapping
         VBuffer<ReadOnlyMemory<char>> labels = default;
         split.TrainSet.Schema["Label"].GetKeyValues(ref labels);
         _categoryLabels = labels.DenseValues().Select(v => v.ToString()).ToArray();

         TrainSchema = split.TrainSet.Schema;

         IDataView predictions = _model.Transform(split.TestSet);
         Metrics = _mlContext.MulticlassClassification.Evaluate(predictions, "Label");
     }

